import { test, expect } from '@playwright/test';

test('Visual comparison between implementation and Golden Master', async ({ page }) => {
  // The baseURL is set to http://localhost:4321 in playwright.config.js
  await page.goto('/');

  // Mask dynamic elements that cause flakiness (e.g., Google Maps)
  const mapContainer = page.locator('.map-container iframe');

  // Compare the current page against the 'golden-master.png' snapshot
  // generated by tests/visual-baseline.spec.js
  await expect(page).toHaveScreenshot('golden-master', {
    fullPage: true,
    mask: [mapContainer],
    maxDiffPixels: 1000,
  });
});
